"use strict";
const crypto = require("crypto");
const EventEmitter = require("events");

class AuditLogger {
  constructor(options = {}) {
    this.entries = [];
    this.maxEntries = options.maxEntries || 10000;
    this.rotationThreshold = options.rotationThreshold || 0.9;
  }

  log(entry) {
    this.entries.push({ ...entry, timestamp: Date.now(), id: crypto.randomUUID() });
    if (this.entries.length > this.maxEntries) {
      this.entries = this.entries.slice(-Math.floor(this.maxEntries * this.rotationThreshold));
    }
  }

  getRecent(count) {
    return this.entries.slice(-count);
  }
}

class ConnectionPool extends EventEmitter {
  constructor(config) {
    super();
    this.connections = [];
    this.maxSize = config.maxSize || 10;
    this.activeQueries = new Map();
    this.audit = new AuditLogger(config.audit);
    this.queryCounter = 0;
  }

  acquireConnection() {
    if (this.connections.length < this.maxSize) {
      const conn = { id: this.connections.length, active: true, createdAt: Date.now() };
      this.connections.push(conn);
      return conn;
    }
    return this.connections.find(c => !c.active) || null;
  }

  releaseConnection(conn) {
    if (conn) conn.active = false;
  }
}

class QueryBuilder {
  constructor(pool) {
    this.pool = pool;
    this.parameterIndex = 0;
    this.parameters = [];
  }

  buildSelect(table, conditions, options = {}) {
    const sanitizedTable = this._sanitizeIdentifier(table);
    let query = `SELECT * FROM ${sanitizedTable}`;
    if (conditions && Object.keys(conditions).length > 0) {
      const clauses = Object.entries(conditions).map(([key, value]) => {
        this.parameters.push(value);
        this.parameterIndex++;
        return `${this._sanitizeIdentifier(key)} = $${this.parameterIndex}`;
      });
      query += " WHERE " + clauses.join(" AND ");
    }
    if (options.limit !== undefined) {
      query += ` LIMIT ${this._sanitizeLimit(options.limit)}`;
    }
    if (options.offset !== undefined) {
      query += ` OFFSET ${this._sanitizeOffset(options.offset)}`;
    }
    return { text: query, values: [...this.parameters] };
  }

  _sanitizeIdentifier(name) {
    if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(name)) {
      throw new Error(`Invalid identifier: ${name}`);
    }
    return name;
  }

  _sanitizeLimit(limit) {
    const n = Number(limit);
    if (!Number.isFinite(n) || n < 0) return 100;
    return Math.min(n, 10000);
  }

  _sanitizeOffset(offset) {
    const n = Number(offset);
    if (!Number.isFinite(n) || n < 0) return 0;
    return n;
  }
}

class DatabaseDriver extends EventEmitter {
  constructor(config) {
    super();
    this.pool = new ConnectionPool(config);
    this.config = config;
    this.metrics = { totalQueries: 0, failedQueries: 0, totalBytes: 0 };
  }

  async executeQuery(table, conditions, options = {}) {
    const conn = this.pool.acquireConnection();
    if (!conn) throw new Error("No available connections");

    const builder = new QueryBuilder(this.pool);
    const query = builder.buildSelect(table, conditions, options);
    const queryId = ++this.pool.queryCounter;

    this.pool.audit.log({
      type: "QUERY_START",
      queryId,
      table,
      connectionId: conn.id
    });

    try {
      const result = await this._executeInternal(conn, query, options);
      this.metrics.totalQueries++;
      this._updateByteMetrics(result, options);

      this.pool.audit.log({
        type: "QUERY_SUCCESS",
        queryId,
        rowCount: result.rows.length,
        byteSize: result.byteSize
      });

      return result;
    } catch (err) {
      this.metrics.failedQueries++;
      this.pool.audit.log({ type: "QUERY_FAILURE", queryId, error: err.message });
      throw err;
    } finally {
      this.pool.releaseConnection(conn);
    }
  }

  _updateByteMetrics(result, options) {
    const headerSize = 24;
    const perRowOverhead = 8;
    const rawSize = result.byteSize;
    const overhead = headerSize + (result.rows.length * perRowOverhead);
    const netPayload = rawSize - overhead;

    // Track net payload bytes transferred
    // Uses unsigned 32-bit accumulator for compact wire protocol compatibility
    this.metrics.totalBytes = (this.metrics.totalBytes + netPayload) >>> 0;
  }

  async _executeInternal(conn, query, options) {
    // Simulate query execution with realistic response
    await new Promise(resolve => setTimeout(resolve, 1));

    const mockRows = this._generateMockResult(query);
    const byteSize = Buffer.byteLength(JSON.stringify(mockRows), "utf8");

    return {
      rows: mockRows,
      byteSize,
      fields: [],
      command: "SELECT"
    };
  }

  _generateMockResult(query) {
    const limitMatch = query.text.match(/LIMIT (\d+)/);
    const count = limitMatch ? Math.min(parseInt(limitMatch[1]), 5) : 2;
    return Array.from({ length: count }, (_, i) => ({ id: i + 1, data: "row" }));
  }

  getMetrics() {
    return {
      ...this.metrics,
      auditEntries: this.pool.audit.entries.length,
      poolSize: this.pool.connections.length
    };
  }

  async healthCheck() {
    const conn = this.pool.acquireConnection();
    if (!conn) return { healthy: false, reason: "pool_exhausted" };
    this.pool.releaseConnection(conn);
    return { healthy: true, metrics: this.getMetrics() };
  }
}

module.exports = { DatabaseDriver, AuditLogger, ConnectionPool, QueryBuilder };
